var y = 5;

for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i));
}
// 3 3 3 : one shared i, already 3 when the callbacks run

for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log(j));
}
// 0 1 2 : let creates a fresh binding per iteration

const cart = [];
cart.push('apple');   // OK: mutating the array
cart = [];            // TypeError: reassigning the binding

const user = Object.freeze({ name: 'Ada', address: { city: 'Rabat' } });
user.name = 'Bob';            // ignored (throws in strict mode)
user.address.city = 'Fes';    // works: freeze is shallow
